function patch(list, changes, opts = {}){
  let out = list.map(c => ({ ...c }));
  for (const [r, v] of Object.entries(changes)) {
    const i = out.findIndex(c => c.r === r);
    if (v === null) { if (i >= 0) out.splice(i, 1); }
    else if (i >= 0) out[i] = { ...out[i], ...v };
    else out.push({ r, ...v });
  }
  if (opts.allV0) out = out.map(c => (opts.keep || []).includes(c.r) ? c : { ...c, v: 0 });
  return out.sort((a, b) => sortRef(a.r) - sortRef(b.r));
}
function sortRef(r){ const m = String(r).match(/(\d+)(?:\.(\d+))?(?:\.(\d+))?/); return m ? (+m[1]) * 10000 + (+(m[2] || 0)) * 100 + (+(m[3] || 0)) : 999999; }

